# Search for tables containing 'pieces' or 'number'
for i, elem in enumerate(data['document']['elements']):
    if elem.get('type') == 'table':
        content = elem.get('content', {})
        if content:
            text = json.dumps(content)
            if 'pieces' in text.lower() or 'number' in text.lower():
                if len(text) < 2000:
                    print(f'Found table at index {i}')
